# Generate Pylance/Pyright type stubs for the m5 package.
# The m5 python package only exists inside the gem5 binary (build/X86/python has
# no importable .py files), so static analysis cannot see `from m5.objects
# import *`. This script runs INSIDE gem5.opt, where m5 is fully populated,
# and dumps every m5.* module as a .pyi stub tree.
#
# Usage: ./build/X86/gem5.opt tests/ucas/gen_stubs.py   (from repo root)
import inspect
import os
import sys
import types

OUT = os.path.join("tests", "ucas", "stubs")

HEADER = (
    "# Generated by tests/ucas/gen_stubs.py (run inside gem5.opt)."
    " Do not edit.\nfrom typing import Any\n\n"
)

CLASS_TMPL = (
    "class {name}:\n"
    "    def __init__(self, *args: Any, **kwargs: Any) -> None: ...\n"
    "    def __getattr__(self, name: str) -> Any: ...\n"
    "    def __setattr__(self, name: str, value: Any) -> None: ...\n"
    "\n"
)


def stub_body(mod):
    lines = []
    for name in sorted(dir(mod)):
        if name.startswith("_"):
            continue
        obj = getattr(mod, name)
        if isinstance(obj, types.ModuleType):
            continue
        if inspect.isclass(obj):
            lines.append(CLASS_TMPL.format(name=name))
        elif callable(obj):
            lines.append(
                f"def {name}(*args: Any, **kwargs: Any) -> Any: ...\n"
            )
        else:
            lines.append(f"{name}: Any\n")
    return HEADER + "\n".join(lines)


def main():
    n_files = 0
    for modname in sorted(
        n for n in sys.modules if n == "m5" or n.startswith("m5.")
    ):
        if "._" in modname:
            continue
        mod = sys.modules[modname]
        if modname == "m5":
            path = os.path.join(OUT, "m5", "__init__.pyi")
        elif hasattr(mod, "__path__"):  # package
            path = os.path.join(OUT, *modname.split("."), "__init__.pyi")
        else:
            path = os.path.join(
                OUT, *modname.split(".")[:-1], modname.split(".")[-1] + ".pyi"
            )
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            f.write(stub_body(mod))
        n_files += 1
    sys.stderr.write(f"gen_stubs: wrote {n_files} stub files under {OUT}\n")


main()
